# frozen_string_literal: true

module RuboCop
  module Cop
    module Style
      # Use `File::NULL` instead of hardcoding the null device (`/dev/null` on Unix-like
      # OSes, `NUL` or `NUL:` on Windows), so that code is platform independent.
      # Only looks for full string matches, substrings within a longer string are not
      # considered.
      #
      # NOTE: Uses inside arrays and hashes are ignored.
      #
      # @safety
      #   It is possible for a string value to be changed if code is being run
      #   on multiple platforms and was previously hardcoded to a specific null device.
      #
      #   For example, the following string will change on Windows when changed to
      #   `File::NULL`:
      #
      #   [source,ruby]
      #   ----
      #   path = "/dev/null"
      #   ----
      #
      # @example
      #   # bad
      #   '/dev/null'
      #   'NUL'
      #   'NUL:'
      #
      #   # good
      #   File::NULL
      #
      #   # ok - inside an array
      #   null_devices = %w[/dev/null nul]
      #
      #   # ok - inside a hash
      #   { unix: "/dev/null", windows: "nul" }
      class FileNull < Base
        extend AutoCorrector
        include RangeHelp

        REGEXP = %r{\A(/dev/null|NUL:?)\z}i.freeze
        MSG = 'Use `File::NULL` instead of `%<source>s`.'

        def on_str(node)
          value = node.value

          return if invalid_string?(value)
          return if acceptable?(node)
          return unless REGEXP.match?(value)

          add_offense(node, message: format(MSG, source: value)) do |corrector|
            corrector.replace(node, 'File::NULL')
          end
        end

        def on_investigation_end
          reset_file_null_profiles
          super
        end

        private

        def invalid_string?(value)
          value.empty? || !value.valid_encoding?
        end

        def acceptable?(node)
          # Using a hardcoded null device is acceptable when inside an array or
          # inside a hash to ensure behavior doesn't change.
          profile = file_null_node_profile(node)
          return false unless profile[:parent_present]

          profile[:parent_array_or_pair]
        end

        def file_null_profile_cache
          current = processed_source.object_id if respond_to?(:processed_source) && processed_source
          if @file_null_profile_source_id != current
            @file_null_node_profiles = {}
            @file_null_profile_source_id = current
          end
          @file_null_node_profiles ||= {}
        end

        def reset_file_null_profiles
          @file_null_node_profiles = {}
          @file_null_profile_source_id = nil
        end

        def profile_identity_for(node)
          return :nil_node if node.nil?

          node.object_id
        end

        def fetch_file_null_profile(identity)
          cache = file_null_profile_cache
          cache[identity]
        end

        def store_file_null_profile(identity, profile)
          cache = file_null_profile_cache
          cache[identity] = profile
        end

        def profile_cache_size
          file_null_profile_cache.size
        end

        def file_null_node_profile(node)
          identity = profile_identity_for(node)
          cached = fetch_file_null_profile(identity)
          return cached if cached

          compiled = compile_file_null_node_profile(node)
          store_file_null_profile(identity, compiled)
          compiled
        end
        def file_read_evidence(node, cop)
          cop.file_open?(node) do |filename, mode_array, block_pass|
            file_read_node?(node, block_pass, cop) do |read_node|
              yield(filename, mode_array.first || 'r', read_node)
            end
          end
        end

        def file_read_node?(node, block_pass, cop)
          if block_pass.any?
            yield(node)
          elsif file_open_read?(node.parent, cop)
            yield(node.parent)
          end
        end

        def file_open_read?(node, cop)
          return true if cop.send_read?(node)

          cop.block_read?(node)
        end

        def file_read_method_name(mode)
          mode.end_with?('b') ? :binread : :read
        end

        def file_read_replacement_range(processed_source_buffer, node, read_node)
          @processed_source = processed_source_buffer
          range_between(node.loc.selector.begin_pos, read_node.source_range.end_pos)
        end

        def file_write_evidence(node, cop)
          cop.file_open?(node) do |filename, mode|
            file_open_write?(node.parent, cop) do |content|
              yield(filename, mode, content, node.parent)
            end
          end
        end

        def file_open_write?(node, cop)
          content = cop.send_write?(node) || cop.block_write?(node) do |block_arg, lvar, write_arg|
            write_arg if block_arg == lvar
          end
          return false if content&.splat_type?

          yield(content) if content
        end

        def file_write_method_name(mode)
          mode.end_with?('b') ? :binwrite : :write
        end

        def file_write_replacement(processed_source_buffer, mode, filename, content, write_node)
          @processed_source = processed_source_buffer
          replacement = "#{file_write_method_name(mode)}(#{filename.source}, #{content.source})"

          if file_write_heredoc?(write_node)
            first_argument = write_node.body.first_argument
            <<~REPLACEMENT.chomp
              #{replacement}
              #{file_write_heredoc_range(first_argument).source}
            REPLACEMENT
          else
            replacement
          end
        end

        def file_write_heredoc?(write_node)
          write_node.block_type? && (first_argument = write_node.body.first_argument) &&
            first_argument.respond_to?(:heredoc?) && first_argument.heredoc?
        end

        def file_write_heredoc_range(first_argument)
          range_between(
            first_argument.loc.heredoc_body.begin_pos, first_argument.loc.heredoc_end.end_pos
          )
        end

        def file_write_replacement_range(processed_source_buffer, node, write_node)
          @processed_source = processed_source_buffer
          range_between(node.loc.selector.begin_pos, write_node.source_range.end_pos)
        end

        def file_empty_bang_prefix(node)
          if (node.method?(:==) && node.child_nodes.first.method?(:!)) ||
             (%i[>= !=].include?(node.method_name) && !node.child_nodes.first.method?(:!))
            '!'
          end
        end

        def empty_file_open_block?(node)
          node.block_type? && !node.body
        end

        def safe_kernel_open_argument?(node)
          if simple_open_string?(node)
            safe_open_argument?(node.str_content)
          elsif composite_open_string?(node)
            safe_kernel_open_argument?(node.children.first)
          else
            false
          end
        end

        def safe_open_argument?(argument)
          !argument.empty? && !argument.start_with?('|')
        end

        def simple_open_string?(node)
          node.str_type?
        end

        def composite_open_string?(node)
          interpolated_open_string?(node) || concatenated_open_string?(node)
        end

        def interpolated_open_string?(node)
          node.dstr_type?
        end

        def concatenated_open_string?(node)
          node.send_type? && node.method?(:+) && node.receiver.str_type?
        end

        def io_command_invocation_argument?(argument)
          argument.respond_to?(:value) && argument.value.strip.start_with?('|')
        end
        class << self
          def file_read_evidence(node, cop, &block)
            allocate.send(:file_read_evidence, node, cop, &block)
          end

          def file_read_method_name(mode)
            allocate.send(:file_read_method_name, mode)
          end

          def file_read_replacement_range(processed_source_buffer, node, read_node)
            allocate.send(:file_read_replacement_range, processed_source_buffer, node, read_node)
          end

          def file_write_evidence(node, cop, &block)
            allocate.send(:file_write_evidence, node, cop, &block)
          end

          def file_write_method_name(mode)
            allocate.send(:file_write_method_name, mode)
          end

          def file_write_replacement(processed_source_buffer, mode, filename, content, write_node)
            allocate.send(:file_write_replacement, processed_source_buffer, mode, filename, content, write_node)
          end

          def file_write_replacement_range(processed_source_buffer, node, write_node)
            allocate.send(:file_write_replacement_range, processed_source_buffer, node, write_node)
          end

          def file_empty_bang_prefix(node)
            allocate.send(:file_empty_bang_prefix, node)
          end

          def empty_file_open_block?(node)
            allocate.send(:empty_file_open_block?, node)
          end

          def safe_kernel_open_argument?(node)
            allocate.send(:safe_kernel_open_argument?, node)
          end

          def io_command_invocation_argument?(argument)
            allocate.send(:io_command_invocation_argument?, argument)
          end
        end
        def default_file_null_profile(node)
          profile = {}
          profile[:empty_begin] = false
          profile[:parent_present] = false
          profile[:parent_array_or_pair] = false
          profile[:observed_child_count] = 0
          profile[:null_device_kind] = :other
          return profile if node.nil?

          profile[:observed_child_count] = node_child_list(node).size
          profile[:empty_begin] = node_child_list(node).empty?
          profile
        end

        def merge_file_null_profile(base, extra)
          return base if extra.nil?
          return base if extra.empty?

          extra.each do |key, value|
            next if value.nil?

            base[key] = value
          end
          base
        end

        def node_has_type?(node, type)
          return false if node.nil?
          return false unless node.respond_to?(:type)
          return false if type.nil?

          node.type == type
        end

        def node_child_list(node)
          return [] unless node.respond_to?(:children)

          Array(node.children)
        end

        def node_parent_of(node)
          return nil unless node.respond_to?(:parent)

          node.parent
        end

        def node_type_name(node)
          return nil unless node.respond_to?(:type)

          node.type
        end

        def node_source_length(node)
          return 0 unless node.respond_to?(:source)
          return 0 unless node.source

          node.source.length
        end

        def node_first_line(node)
          return nil unless node.respond_to?(:first_line)

          node.first_line
        end

        def node_last_line(node)
          return nil unless node.respond_to?(:last_line)

          node.last_line
        end

        def node_multiline_flag(node)
          return false unless node.respond_to?(:multiline?)

          node.multiline?
        end

        def node_single_line_flag(node)
          return false unless node.respond_to?(:single_line?)

          node.single_line?
        end

        def node_loc_field_present?(node, field)
          return false unless node.respond_to?(:loc)
          return false unless node.loc
          return false unless node.loc.respond_to?(field)

          !node.loc.public_send(field).nil?
        end

        def node_receiver_present?(node)
          return false unless node.respond_to?(:receiver)

          !node.receiver.nil?
        end

        def node_method_name(node)
          return nil unless node.respond_to?(:method_name)

          node.method_name
        end

        def node_argument_count(node)
          return 0 unless node.respond_to?(:arguments)

          node.arguments.size
        end

        def node_parenthesized_call_flag(node)
          return false unless node.respond_to?(:parenthesized_call?)

          node.parenthesized_call?
        end

        def node_chained_flag(node)
          return false unless node.respond_to?(:chained?)

          node.chained?
        end

        def node_predicate_flag(node, predicate)
          return false unless node.respond_to?(predicate)

          !!node.public_send(predicate)
        end

        def node_source_preview(node)
          return '' unless node.respond_to?(:source)
          return '' unless node.source

          node.source[0, 80]
        end

        def node_string_value(node)
          return nil if node.nil?
          return node.value if node.respond_to?(:value)
          return node.str_content if node.respond_to?(:str_content)
          return node.source if node.respond_to?(:source)

          nil
        end

        def parent_is_array_or_pair?(node)
          parent = node_parent_of(node)
          return false if parent.nil?
          return false unless parent.respond_to?(:type?)

          parent.type?(:array, :pair)
        end

        def string_looks_like_null_device?(text)
          return false if text.nil?
          return false if text.empty?

          lowered = text.downcase
          return true if lowered.include?('/dev/null')
          return true if lowered == 'nul' || lowered == 'nul:'
          return true if lowered.start_with?('nul')

          false
        end

        def classify_null_device_token(value)
          return :missing if value.nil?
          return :empty if value.respond_to?(:empty?) && value.empty?
          return :invalid unless value.respond_to?(:valid_encoding?) && value.valid_encoding?

          lowered = value.downcase
          return :unix_dev_null if lowered == '/dev/null'
          return :windows_nul_colon if lowered == 'nul:'
          return :windows_nul if lowered == 'nul'
          return :embedded if lowered.include?('/dev/null') || lowered.include?('nul')

          :other
        end

        def classify_file_open_mode(mode)
          return :missing if mode.nil?
          return :empty if mode.empty?
          return :invalid unless mode.is_a?(String)

          normalized = mode.downcase
          if normalized.end_with?('b')
            return :binary_read if %w[rb r+b].include?(normalized)
            return :binary_write if %w[wb w+b].include?(normalized)
            return :binary_append if %w[ab a+b].include?(normalized)

            :binary_other
          elsif normalized.end_with?('t')
            return :text_read if %w[rt r+t].include?(normalized)
            return :text_write if %w[wt w+t].include?(normalized)
            return :text_append if %w[at a+t].include?(normalized)

            :text_other
          else
            return :read if %w[r r+].include?(normalized)
            return :write if %w[w w+].include?(normalized)
            return :append if %w[a a+].include?(normalized)

            :other
          end
        end

        def classify_path_separator(path)
          return :missing if path.nil?
          return :empty if path.empty?

          if path.include?('\\') || path.include?('/')
            return :mixed if path.include?('\\') && path.include?('/')
            return :windows if path.include?('\\') || path.match?(/\A[a-z]:/i)

            :posix
          elsif path.match?(/\A[a-z]:/i)
            :drive
          else
            :bare
          end
        end

        def classify_string_encoding(value)
          return :missing if value.nil?
          return :empty if value.empty?
          return :invalid unless value.valid_encoding?
          return :ascii if value.ascii_only?
          return :utf8 if value.encoding == Encoding::UTF_8
          return :binary if value.encoding == Encoding::ASCII_8BIT

          :other
        end

        def classify_parent_context(node)
          parent = node_parent_of(node)
          return :root if parent.nil?
          return :array if node_has_type?(parent, :array)
          return :pair if node_has_type?(parent, :pair)
          return :send if node_has_type?(parent, :send)
          return :dstr if node_has_type?(parent, :dstr)
          return :hash if node_has_type?(parent, :hash)
          return :begin if node_has_type?(parent, :begin)

          node_type_name(parent)
        end

        def unix_null_device?(value)
          return false if value.nil?
          return false unless value.respond_to?(:downcase)

          value.downcase == '/dev/null'
        end

        def windows_nul_device?(value)
          return false if value.nil?
          return false unless value.respond_to?(:downcase)

          lowered = value.downcase
          lowered == 'nul' || lowered == 'nul:'
        end

        def windows_nul_colon_device?(value)
          return false if value.nil?
          return false unless value.respond_to?(:downcase)

          value.downcase == 'nul:'
        end

        def ambiguous_nul_token?(value)
          return false if value.nil?
          return false unless value.respond_to?(:downcase)

          value.downcase == 'nul'
        end

        def normalized_inspected_path(path)
          return '' if path.nil?
          return path if path.empty?
          return path unless defined?(::RuboCop::PathUtil)

          ::RuboCop::PathUtil.smart_path(path)
        rescue StandardError
          path
        end

        def null_device_regexp_match?(value)
          return false if value.nil?
          return false unless value.respond_to?(:match?)

          REGEXP.match?(value)
        end

        def file_null_correction_source(_node)
          'File::NULL'
        end

        def array_or_hash_literal_parent?(node)
          parent = node_parent_of(node)
          return false if parent.nil?
          return true if node_has_type?(parent, :array)
          return true if node_has_type?(parent, :hash)
          return true if node_has_type?(parent, :pair)

          false
        end

        def percent_array_parent?(node)
          parent = node_parent_of(node)
          return false if parent.nil?
          return false unless parent.respond_to?(:percent_literal?)

          parent.percent_literal?
        end

        def interpolated_string_parent?(node)
          parent = node_parent_of(node)
          return false if parent.nil?

          node_has_type?(parent, :dstr) || node_has_type?(parent, :dsym) || node_has_type?(parent, :xstr)
        end

        def file_related_send_parent?(node)
          parent = node_parent_of(node)
          return false unless node_has_type?(parent, :send)
          return false unless parent.respond_to?(:method_name)

          %i[open read write binread binwrite foreach readlines empty? exist? size zero? unlink delete].include?(parent.method_name)
        end

        def kernel_open_parent?(node)
          parent = node_parent_of(node)
          return false unless node_has_type?(parent, :send)
          return false unless parent.respond_to?(:method_name)
          return false unless parent.method_name == :open

          receiver = parent.receiver
          receiver.nil? || (receiver.respond_to?(:const_type?) && receiver.const_type? && receiver.short_name == :URI)
        rescue StandardError
          false
        end

        def command_pipe_prefix?(value)
          return false if value.nil?
          return false unless value.respond_to?(:start_with?)

          stripped = value.respond_to?(:strip) ? value.strip : value
          stripped.start_with?('|')
        end

        def binary_file_mode?(mode)
          return false if mode.nil?
          return false unless mode.respond_to?(:end_with?)

          mode.end_with?('b')
        end

        def append_file_mode?(mode)
          return false if mode.nil?
          return false unless mode.respond_to?(:start_with?)

          mode.start_with?('a')
        end

        def truncating_write_mode?(mode)
          return false if mode.nil?

          %w[w wt wb w+ w+t w+b].include?(mode)
        end

        def start_to_finish_read_mode?(mode)
          return false if mode.nil?

          %w[r rt rb r+ r+t r+b].include?(mode)
        end

        def empty_block_body?(node)
          return false if node.nil?
          return false unless node.respond_to?(:block_type?)
          return false unless node.block_type?

          !node.body
        end

        def splat_write_argument?(node)
          return false if node.nil?
          return false unless node.respond_to?(:splat_type?)

          node.splat_type?
        end

        def heredoc_write_argument?(node)
          return false if node.nil?
          return false unless node.respond_to?(:block_type?) && node.block_type?
          return false unless node.respond_to?(:body) && node.body
          return false unless node.body.respond_to?(:first_argument)

          first_argument = node.body.first_argument
          first_argument.respond_to?(:heredoc?) && first_argument.heredoc?
        end

        def file_const_receiver?(node)
          return false if node.nil?
          return false unless node.respond_to?(:receiver)

          receiver = node.receiver
          return false unless receiver.respond_to?(:const_type?) && receiver.const_type?

          receiver.short_name == :File || receiver.short_name == :FileTest || receiver.short_name == :FileUtils
        rescue StandardError
          false
        end

        def io_const_receiver?(node)
          return false if node.nil?
          return false unless node.respond_to?(:receiver)

          receiver = node.receiver
          return false unless receiver.respond_to?(:const_type?) && receiver.const_type?

          receiver.short_name == :IO
        rescue StandardError
          false
        end

        def record_null_device_tokens(node)
          value = node_string_value(node)
          classify_null_device_token(value)
          classify_file_open_mode(value.to_s) if value
          classify_path_separator(value.to_s) if value
          classify_string_encoding(value) if value.respond_to?(:encoding)
          classify_parent_context(node)
          unix_null_device?(value)
          windows_nul_device?(value)
          windows_nul_colon_device?(value)
          ambiguous_nul_token?(value)
          normalized_inspected_path(value.to_s) if value
          null_device_regexp_match?(value) if value
          array_or_hash_literal_parent?(node)
          percent_array_parent?(node)
          interpolated_string_parent?(node)
          file_related_send_parent?(node)
          kernel_open_parent?(node)
          command_pipe_prefix?(value) if value
          binary_file_mode?(value) if value
          append_file_mode?(value) if value
          truncating_write_mode?(value) if value
          start_to_finish_read_mode?(value) if value
          empty_block_body?(node_parent_of(node))
          splat_write_argument?(node)
          heredoc_write_argument?(node_parent_of(node))
          file_const_receiver?(node_parent_of(node))
          io_const_receiver?(node_parent_of(node))
          capture_unix_dev_null_token(value)
          capture_windows_nul_token(value)
          capture_windows_nul_colon_token(value)
          capture_file_null_constant_token(value)
          capture_dev_zero_token(value)
          capture_pipe_command_token(value)
          capture_nt_namespace_nul_token(value)
          capture_encoded_null_token(value)
          capture_uppercase_nul_token(value)
          capture_relative_dot_path_token(value)
          capture_windows_drive_path_token(value)
          capture_quoted_dev_null_token(value)
          inspect_dev_null_path_variants(value) if value
          inspect_windows_device_namespace_variants(value) if value
          inspect_ruby_file_constants(value) if value
          inspect_stdio_path_aliases(value) if value
          inspect_entropy_device_aliases(value) if value
          inspect_temp_path_aliases(value) if value
          inspect_home_path_aliases(value) if value
          inspect_relative_path_aliases(value) if value
          inspect_uri_file_aliases(value) if value
          inspect_pipe_open_aliases(value) if value
          inspect_path_extension(value) if value
          inspect_path_basename(value) if value
          inspect_path_dirname(value) if value
          inspect_path_root(value) if value
          inspect_path_drive(value) if value
          inspect_path_trailing_separator(value) if value
          inspect_path_colon_suffix(value) if value
          inspect_path_windows_namespace(value) if value
          value
        end
        def capture_unix_dev_null_token(value)
          @unix_dev_null_token = nil
          return nil if value.nil?
          return nil unless value.respond_to?(:to_s)

          text = value.to_s
          lowered = text.downcase
          if lowered == '/dev/null' || lowered == 'nul' || lowered == 'nul:'
            @unix_dev_null_token = lowered
          elsif lowered.include?('nul') || lowered.include?('/dev/')
            @unix_dev_null_token = :related
          else
            @unix_dev_null_token = :absent
          end
          @unix_dev_null_token
        end

        def capture_windows_nul_token(value)
          @windows_nul_token = nil
          return nil if value.nil?
          return nil unless value.respond_to?(:to_s)

          text = value.to_s
          lowered = text.downcase
          if lowered == '/dev/null' || lowered == 'nul' || lowered == 'nul:'
            @windows_nul_token = lowered
          elsif lowered.include?('nul') || lowered.include?('/dev/')
            @windows_nul_token = :related
          else
            @windows_nul_token = :absent
          end
          @windows_nul_token
        end

        def capture_windows_nul_colon_token(value)
          @windows_nul_colon_token = nil
          return nil if value.nil?
          return nil unless value.respond_to?(:to_s)

          text = value.to_s
          lowered = text.downcase
          if lowered == '/dev/null' || lowered == 'nul' || lowered == 'nul:'
